record.field:
linked_department = record.x_studio_department
if linked_department:
    linked_department.write({
        'manager_id': record.x_studio_employe.id,
    })
else:
    new_department = env['hr.department'].create({
        'name': record.x_name,
        'manager_id': record.x_studio_employe.id,})
    record['x_studio_department'] = new_department

linked_department = record.x_studio_organisation
parent = record.x_studio_parent_department if record.x_studio_parent_department else record.x_studio_faculty
if linked_department:
    linked_department.write({
        'manager_id': record.x_studio_responsible.id,
        'parent_id':parent.id,
    })
else:
    new_department = env['hr.department'].create({
        'name': record.x_name,
        'manager_id': record.x_studio_responsible.id,
                'parent_id':parent.id,
    })
    record['x_studio_organisation'] = new_department
